const binaryData = $input.item.binary.submitted_file;
const fileName = binaryData.fileName.toLowerCase();
const mimeType = binaryData.mimeType;

const allowedExtensions = ['.eml', '.msg'];
const hasValidExt = allowedExtensions.some(ext => fileName.endsWith(ext));

// Google Drive assigns specific mimetypes to uploaded files, or octet-stream
const isAcceptedMime = mimeType.includes('message/rfc822') || 
                       mimeType.includes('application/vnd.ms-outlook') || 
                       mimeType.includes('octet-stream');

if (!hasValidExt && !isAcceptedMime) {
  throw new Error(`Security Exception: Unauthorized file type submitted (${fileName})`);
}

return $input.item;
